"""Минимальный генератор PPTX без внешних библиотек."""
from __future__ import annotations

from html import escape
from pathlib import Path
from zipfile import ZIP_DEFLATED, ZipFile

ROOT = Path(__file__).resolve().parents[1]
OUT = ROOT / "results" / "presentations" / "презентация_судья_E1-E4.pptx"
W, H = 12192000, 6858000
NAVY, WHITE, ORANGE, BLUE, GRAY, LIGHT, GREEN, RED, D1D5DB = "111827", "FFFFFF", "F59E0B", "2563EB", "4B5563", "F3F4F6", "15803D", "B91C1C", "D1D5DB"


def esc(text: str) -> str:
    return escape(text, quote=False)


def color(value: str) -> str:
    return f'<a:solidFill><a:srgbClr val="{value}"/></a:solidFill>'


def shape(text: str, x: int, y: int, cx: int, cy: int, size=2200, fill=None, bold=False, font=GRAY):
    fill_xml = f"<a:solidFill>{color(fill)[13:-13]}</a:solidFill>" if fill else "<a:noFill/>"
    # Keep text boxes transparent; colored rectangles are separate shapes.
    if fill:
        fill_xml = color(fill)
    else:
        fill_xml = "<a:noFill/>"
    b = ' b="1"' if bold else ''
    return f'''<p:sp><p:nvSpPr><p:cNvPr id="2" name="text"/><p:cNvSpPr txBox="1"/><p:nvPr/></p:nvSpPr><p:spPr><a:xfrm><a:off x="{x}" y="{y}"/><a:ext cx="{cx}" cy="{cy}"/></a:xfrm><a:prstGeom prst="rect"><a:avLst/></a:prstGeom>{fill_xml}<a:ln><a:noFill/></a:ln></p:spPr><p:txBody><a:bodyPr wrap="square"/><a:lstStyle/>{''.join(f'<a:p><a:r><a:rPr lang="ru-RU" sz="{size}"{b}>{color(font)}<a:latin typeface="Aptos"/></a:rPr><a:t>{esc(line)}</a:t></a:r><a:endParaRPr lang="ru-RU" sz="{size}"/></a:p>' for line in text.split(chr(10)))}</p:txBody></p:sp>'''


def rect(x, y, cx, cy, fill):
    return f'''<p:sp><p:nvSpPr><p:cNvPr id="3" name="box"/><p:cNvSpPr/><p:nvPr/></p:nvSpPr><p:spPr><a:xfrm><a:off x="{x}" y="{y}"/><a:ext cx="{cx}" cy="{cy}"/></a:xfrm><a:prstGeom prst="rect"><a:avLst/></a:prstGeom>{color(fill)}<a:ln><a:noFill/></a:ln></p:spPr></p:sp>'''


def slide(title: str, body: list[tuple[str, int, int, int, int, int, str, bool]], kicker="E1–E4 · оценка MCP-ассистента") -> str:
    items = [rect(0, 0, W, 1250000, NAVY), shape(kicker, 450000, 260000, 5000000, 250000, 1200, None, True, ORANGE), shape(title, 450000, 560000, 11200000, 500000, 2600, None, True, WHITE)]
    for text, x, y, cx, cy, size, font, bold in body:
        items.append(shape(text, x, y, cx, cy, size, None, bold, font))
    tree = '<p:nvGrpSpPr><p:cNvPr id="1" name=""/><p:cNvGrpSpPr/><p:nvPr/></p:nvGrpSpPr><p:grpSpPr/>' + ''.join(items)
    return f'''<?xml version="1.0" encoding="UTF-8" standalone="yes"?><p:sld xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main" xmlns:p="http://schemas.openxmlformats.org/presentationml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><p:cSld><p:spTree>{tree}</p:spTree></p:cSld><p:clrMapOvr><a:masterClrMapping/></p:clrMapOvr></p:sld>'''


def rels(target: str) -> str:
    return f'''<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/slideLayout" Target="../slideLayouts/slideLayout1.xml"/></Relationships>'''


